                elif ansi_codes is not None and ansi_codes.startswith("["):
                    codes = ansi_codes[1:].split(";")
                    iter_codes = iter(codes)
                    while True:
                        try:
                            code = int(next(iter_codes))
                        except StopIteration:
                            break

                        if code == 0:
                            self.style = Style()
                        elif code == 39:
