def split_cells(self, cut: int) -> Tuple["Segment", "Segment"]:
        """Split segment in to two segments at the specified column.

        If the cut point falls in the middle of a 2-cell wide character then it is replaced
        by two spaces, to preserve the display width of the parent segment.

        Returns:
            Tuple[Segment, Segment]: Two segments.
        """
        text, style, control = self
        if cut >= self.cell_length:
            return self, Segment("", style, control)

        pos = cut
        before = text[:pos]
        cell_pos = cell_len(before)
        if cell_pos == cut:
            return (
                Segment(before, style, control),
                Segment(text[pos:], style, control),
            )
        if cell_pos < cut:
            while pos:
                pos += 1
                before = text[:pos]
                cell_pos = cell_len(before)
                if cell_pos == cut:
                    return (
                        Segment(before, style, control),
                        Segment(text[pos:], style, control),
                    )
                if cell_pos > cut:
                    return (
                        Segment(before[:-1] + " ", style, control),
                        Segment(" " + text[pos:], style, control),
                    )
        elif cell_pos > cut:
            while pos:
                pos -= 1
                before = text[:pos]
                cell_pos = cell_len(before)
                if cell_pos == cut:
                    return (
                        Segment(before, style, control),
                        Segment(text[pos:], style, control),
                    )
                if cell_pos < cut:
                    return (
                        Segment(before[:pos] + " ", style, control),
                        Segment(" " + text[pos + 1 :], style, control),
                    )
        return (Segment("", style, control), self)

